async function testFile(fileName) {
    console.log(`\n================== TESTING ${fileName} ==================`);
    const chrome = spawn('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe', [
        '--remote-debugging-port=9225',
        '--headless=new',
        '--no-sandbox',
        '--user-data-dir=' + path.join(__dirname, 'temp_prof_test')
    ]);

    await new Promise(r => setTimeout(r, 1500));
    try {
        const filePath = path.resolve(__dirname, fileName);
        const fileUrl = 'file:///' + filePath.replace(/\\/g, '/');
        const tab = await (await fetch('http://127.0.0.1:9225/json/new?' + encodeURIComponent(fileUrl), { method: 'PUT' })).json();
        const ws = new WebSocket(tab.webSocketDebuggerUrl);

        const logs = [];
        const errors = [];

        ws.onmessage = (e) => {
            const data = JSON.parse(e.data);
            if (data.method === 'Runtime.consoleAPICalled') {
                const text = data.params.args.map(a => a.value || JSON.stringify(a)).join(' ');
                logs.push(`[${data.params.type}] ${text}`);
            }
            if (data.method === 'Runtime.exceptionThrown') {
                errors.push(JSON.stringify(data.params.exceptionDetails));
            }
        };

        await new Promise(r => ws.onopen = r);

        let reqId = 1;
        function send(method, params = {}) {
            return new Promise(resolve => {
                const id = reqId++;
                const handler = (e) => {
                    const data = JSON.parse(e.data);
                    if (data.id === id) {
                        ws.removeEventListener('message', handler);
                        resolve(data.result);
                    }
                };
                ws.addEventListener('message', handler);
                ws.send(JSON.stringify({ id, method, params }));

